use crate::db::{CostCarryoverRecord, CreateCostCarryoverRecordInput, Database, UpdateCostCarryoverRecordInput}; use tauri::State;
fn opt(v:Option<&String>)->Option<&str>{v.map(String::as_str).map(str::trim).filter(|x|!x.is_empty())}
fn valid(batch:&str,date:&str,method:&str,source:&str,item:&str,debit:&str,credit:&str,cost:f64)->Result<(),String>{if batch.trim().is_empty()||date.trim().is_empty()||method.trim().is_empty()||source.trim().is_empty()||item.trim().is_empty()||debit.trim().is_empty()||credit.trim().is_empty()||cost<0.0{Err("结转批次、日期、计价方法、来源、存货和科目不能为空，成本不得小于零".into())}else{Ok(())}}
#[tauri::command] pub async fn get_cost_carryover_records(company_id:String,period:String,db:State<'_,Database>)->Result<Vec<CostCarryoverRecord>,String>{sqlx::query_as("SELECT * FROM cost_carryover_records WHERE company_id=? AND period=? ORDER BY carryover_date DESC, created_at DESC").bind(company_id).bind(period).fetch_all(db.pool()).await.map_err(|e|format!("查询成本结转记录失败: {e}"))}
#[tauri::command] pub async fn create_cost_carryover_record(i:CreateCostCarryoverRecordInput,db:State<'_,Database>)->Result<CostCarryoverRecord,String>{if i.company_id.trim().is_empty()||i.period.trim().is_empty(){return Err("账套和账期不能为空".into())}valid(&i.batch_no,&i.carryover_date,&i.valuation_method,&i.source_bill_no,&i.inventory_name,&i.debit_subject,&i.credit_subject,i.cost_amount)?;let id=uuid::Uuid::new_v4().to_string();sqlx::query("INSERT INTO cost_carryover_records (id,company_id,period,batch_no,carryover_date,valuation_method,source_bill_no,inventory_name,debit_subject,credit_subject,cost_amount,difference_amount,voucher_no,status,source_document) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)").bind(&id).bind(i.company_id.trim()).bind(i.period.trim()).bind(i.batch_no.trim()).bind(i.carryover_date.trim()).bind(i.valuation_method.trim()).bind(i.source_bill_no.trim()).bind(i.inventory_name.trim()).bind(i.debit_subject.trim()).bind(i.credit_subject.trim()).bind(i.cost_amount).bind(i.difference_amount.unwrap_or(0.0)).bind(opt(i.voucher_no.as_ref())).bind(opt(i.status.as_ref()).unwrap_or("待确认")).bind(opt(i.source_document.as_ref())).execute(db.pool()).await.map_err(|e|format!("新增成本结转记录失败: {e}"))?;sqlx::query_as("SELECT * FROM cost_carryover_records WHERE id=?").bind(id).fetch_one(db.pool()).await.map_err(|e|format!("查询新增成本结转记录失败: {e}"))}
#[tauri::command] pub async fn update_cost_carryover_record(i:UpdateCostCarryoverRecordInput,db:State<'_,Database>)->Result<CostCarryoverRecord,String>{valid(&i.batch_no,&i.carryover_date,&i.valuation_method,&i.source_bill_no,&i.inventory_name,&i.debit_subject,&i.credit_subject,i.cost_amount)?;let r=sqlx::query("UPDATE cost_carryover_records SET batch_no=?,carryover_date=?,valuation_method=?,source_bill_no=?,inventory_name=?,debit_subject=?,credit_subject=?,cost_amount=?,difference_amount=?,voucher_no=?,status=?,source_document=?,updated_at=datetime('now') WHERE id=? AND company_id=?").bind(i.batch_no.trim()).bind(i.carryover_date.trim()).bind(i.valuation_method.trim()).bind(i.source_bill_no.trim()).bind(i.inventory_name.trim()).bind(i.debit_subject.trim()).bind(i.credit_subject.trim()).bind(i.cost_amount).bind(i.difference_amount.unwrap_or(0.0)).bind(opt(i.voucher_no.as_ref())).bind(opt(i.status.as_ref()).unwrap_or("待确认")).bind(opt(i.source_document.as_ref())).bind(&i.id).bind(&i.company_id).execute(db.pool()).await.map_err(|e|format!("更新成本结转记录失败: {e}"))?;if r.rows_affected()==0{return Err("未找到当前账套的成本结转记录".into())}sqlx::query_as("SELECT * FROM cost_carryover_records WHERE id=? AND company_id=?").bind(i.id).bind(i.company_id).fetch_one(db.pool()).await.map_err(|e|format!("查询更新成本结转记录失败: {e}"))}
